import {api,el,button,message,confirmAction} from './common.js';
let guests=[];const login=document.querySelector('#login'),dashboard=document.querySelector('#dashboard'),status=document.querySelector('#admin-status');const labels={pending:'Por confirmar',yes:'Confirmado',no:'Não participa'};
function invite(g){const u=new URL('/',location.origin);u.searchParams.set('convite',g.token);return u.href}
function editForm(title,fields,onSave){const d=el('dialog'),form=el('form');form.append(el('h2',title));const inputs={};for(const [key,label,value,type] of fields){const id='edit-'+key;const l=el('label',label);l.htmlFor=id;const input=el(type==='textarea'?'textarea':type==='select'?'select':'input');input.id=id;if(type==='select'){for(const [v,t]of Object.entries(labels)){const o=el('option',t);o.value=v;input.append(o)}}else if(type!=='textarea')input.type='text';input.value=value;inputs[key]=input;form.append(l,input)}const actions=el('div',undefined,'actions');actions.append(button('Cancelar',()=>d.close(),'secondary'));const save=el('button','Guardar');save.type='submit';actions.append(save);form.append(actions);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{await onSave(Object.fromEntries(Object.entries(inputs).map(([k,i])=>[k,i.value])));d.close();await load()}catch(err){await message(err.message)}finally{save.disabled=false}};d.append(form);d.addEventListener('close',()=>d.remove(),{once:true});document.body.append(d);d.showModal()}
function renderGuests(){const list=document.querySelector('#guests');list.replaceChildren();const q=document.querySelector('#search').value.toLowerCase();for(const g of guests.filter(g=>(g.name+' '+g.phone).toLowerCase().includes(q))){const card=el('article',undefined,'admin-item');card.append(el('h3',g.name),el('p',`${labels[g.rsvp]} · ${g.active?'Activo':'Desactivado'}${g.phone?' · '+g.phone:''}`,'small'));const link=el('a',invite(g),'small');link.href=invite(g);link.target='_blank';link.rel='noopener noreferrer';card.append(link);const actions=el('div',undefined,'actions');actions.append(button('Copiar link',async()=>{try{await navigator.clipboard.writeText(invite(g));await message('Link copiado.')}catch{await message('Seleccione e copie o link mostrado no cartão.')}}),button('Editar',()=>editForm('Editar convidado',[['name','Nome',g.name],['phone','Telefone',g.phone],['rsvp','Presença',g.rsvp,'select']],b=>api('/api/admin/guests/'+g.id,{method:'PATCH',body:b})),'secondary'),button(g.active?'Desactivar':'Reactivar',async()=>{if(!await confirmAction(g.active?'Desactivar este convite? As reservas ainda não compradas serão libertadas.':'Reactivar este convite?'))return;await api('/api/admin/guests/'+g.id,{method:'PATCH',body:{active:!g.active}});await load()},'secondary'));if(g.phone){const a=el('a','Enviar convite no WhatsApp','btn secondary');a.href='https://wa.me/'+g.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(`Olá ${g.name}! Aniceta e Kerusso convidam para o seu casamento, em 20/02/2027. Este é o seu convite pessoal: ${invite(g)}`);a.target='_blank';a.rel='noopener noreferrer';actions.append(a)}card.append(actions);list.append(card)}if(!list.childNodes.length)list.append(el('p','Nenhum convidado encontrado.'))}
async function load(){try{const data=await api('/api/admin/guests');guests=data.guests;login.hidden=true;dashboard.hidden=false;status.textContent='';const active=guests.filter(g=>g.active);const stats=document.querySelector('#stats');stats.replaceChildren(...[['Activos',active.length],['Confirmados',active.filter(g=>g.rsvp==='yes').length],['Por confirmar',active.filter(g=>g.rsvp==='pending').length],['Não participam',active.filter(g=>g.rsvp==='no').length]].map(([l,n])=>el('span',`${l}: ${n}`)));renderGuests();const {gifts}=await api('/api/admin/gifts'),list=document.querySelector('#admin-gifts');list.replaceChildren();for(const g of gifts){const card=el('article',undefined,'card');card.append(el('h3',g.name),el('p',g.description),el('p',`${{available:'Disponível',reserved:'Reservado',purchased:'Comprado'}[g.status]}${g.guest_name?' · '+g.guest_name:''}`));const actions=el('div',undefined,'actions');actions.append(button('Editar',()=>editForm('Editar presente',[['name','Nome',g.name],['description','Descrição',g.description,'textarea']],b=>api('/api/admin/gifts/'+g.id,{method:'PATCH',body:b})),'secondary'));if(g.status!=='available')actions.append(button('Tornar disponível',async()=>{if(!await confirmAction('Tornar este presente disponível? A reserva ou confirmação de compra será removida.'))return;await api('/api/admin/gifts/'+g.id,{method:'PATCH',body:{reset:true}});await load()},'secondary'));card.append(actions);list.append(card)}}catch(e){status.textContent=e.status===401?'Inicie sessão para gerir os convidados.':e.message;if(e.status===401){login.hidden=false;dashboard.hidden=true}}}
login.onsubmit=async e=>{e.preventDefault();const b=login.querySelector('button');b.disabled=true;try{await api('/api/admin/login',{method:'POST',body:{password:document.querySelector('#password').value}});document.querySelector('#password').value='';await load()}catch(err){status.textContent=err.message}finally{b.disabled=false}};
document.querySelector('#guest-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('/api/admin/guests',{method:'POST',body:{name:document.querySelector('#new-name').value,phone:document.querySelector('#new-phone').value}});e.target.reset();await load()}catch(err){await message(err.message)}finally{b.disabled=false}};
document.querySelector('#gift-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('/api/admin/gifts',{method:'POST',body:{name:document.querySelector('#gift-name').value,description:document.querySelector('#gift-description').value}});e.target.reset();await load()}catch(err){await message(err.message)}finally{b.disabled=false}};
document.querySelector('#search').oninput=renderGuests;document.querySelector('#refresh').onclick=load;
document.querySelector('#logout').onclick=async()=>{await api('/api/admin/logout',{method:'POST',body:{}});dashboard.hidden=true;login.hidden=false;guests=[];document.querySelector('#guests').replaceChildren();document.querySelector('#admin-gifts').replaceChildren();status.textContent='Sessão terminada.'};
document.querySelector('#export').onclick=()=>{const safe=v=>{v=String(v??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"'};const csv='\ufeff'+[['Nome','Telefone','Presença','Activo','Link'],...guests.map(g=>[g.name,g.phone,labels[g.rsvp],g.active?'Sim':'Não',invite(g)])].map(row=>row.map(safe).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=el('a');a.href=url;a.download='convidados-aniceta-kerusso.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};load();
